    subtitle: { en: "A classic summary — simple but powerful", es: "Un resumen clásico — simple pero poderoso", ko: "고전적인 요약 — 간단하지만 강력합니다", zh: "经典总结——简单但强大", ja: "古典的な要約 — シンプルだが強力" },
